# Mathematical source oracle, no production code imported.
cases=[]
for length in [0.5,1.19,1.2,2.4,8,20]:
 for phase in [0,0.6,1.2]:
  count=math.floor(length/1.2000000476837158)+1
  if count==1:count=0
  mid=-length/2;a=-1.5/(mid*mid);links=[]
  for i in range(min(count,15)):
   z=-1.2000000476837158*(i+1)+phase;y=a*(z-mid)**2+1.5;alpha=1
   if i==0:
    if z>-1.2000000476837158:alpha=(z/-1.2000000476837158)**6
   elif i==count-1:alpha=(phase/1.2000000476837158)**2
   links.append({'index':i,'local_position':[0,y,z],'x_degrees':180-math.atan(2*a*(z-mid))*57.295780181884766,'alpha':max(0,min(1,alpha))})
  cases.append({'distance':length,'phase':phase,'requested_count':count,'visible_allocated_count':min(count,15),'links':links})
(O/'data/targeting_math_oracle.json').write_text(json.dumps(cases,indent=2))
